module tb;
    logic       clk;
    logic [7:0] in;
    logic [7:0] pedge;

    TopModule dut (
        .clk(clk),
        .in(in),
        .pedge(pedge)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        in = 8'h00;
        @(posedge clk);
        #1;

        // Test 1: all 0 to all 1 transition
        in = 8'hFF;
        @(posedge clk);
        #1;
        if (pedge !== 8'hFF) begin
            $display("SELFTEST FAIL: Expected pedge = 8'hFF, got %h", pedge);
            $finish;
        end

        // Next cycle should be 0
        @(posedge clk);
        #1;
        if (pedge !== 8'h00) begin
            $display("SELFTEST FAIL: Expected pedge = 8'h00, got %h", pedge);
            $finish;
        end

        // Test 2: specific bit transitions
        in = 8'b00000001;
        @(posedge clk); // in_d becomes 8'hFF, in is 00000001 -> pedge = 00000001 & ~8'hFF = 0
        #1;

        // Next cycle
        @(posedge clk); // in_d was 01, in is 01 -> pedge = 0
        #1;

        in = 8'b00000011; // bit 1 transitions 0->1
        @(posedge clk);
        #1;
        if (pedge !== 8'b00000010) begin
            $display("SELFTEST FAIL: Expected pedge = 8'h02, got %h", pedge);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
